    [1292880] = { en = "When struck in combat has a $h% chance of inflicting $1292879s1 Nature damage to the attacker.", description = "Quando vieni colpito in combattimento, hai una probabilità del $h% di infliggere $1292879s1 danni da Natura all'attaccante." },
    [1293003] = { en = "Fire damage taken increased by $s1%.", description = "Danni da Fuoco subiti aumentati del $s1%." },
    [1293020] = { en = "Fires an instant Shot that divides multiple times to strike up to $x targets. Your initial target takes weapon damage plus $s1 and each subsequent target takes 35% less damage. Hydra Shot shares its cooldown with Arcane Shot.", description = "Spara un Colpo istantaneo che si divide più volte per colpire fino a $x bersagli. Il bersaglio iniziale subisce i danni dell'arma più $s1, mentre ogni bersaglio successivo subisce il 35% di danni in meno. Il tempo di recupero di Colpo dell'Idra è condiviso con Tiro Arcano." },
    [1293085] = { en = "Restore $s1 charges to a Manual Crowd Pummeler device in your possession.", description = "Ripristina $s1 cariche a un Punitore della folla manuale in tuo possesso." },
    [1293168] = { en = "Gain the ability to purchase and craft Class Tier 1 Legging recipes from Aisarra Nightmeadow.", description = "Ottieni la possibilità di acquistare e creare ricette di Gambali di classe di Grado 1 da Aisarra Nightmeadow." },
    [1293183] = { en = "Hurl spikes at the target, dealing $s1 Physical damage and jumping to ${$x1-1} additional nearby enemy.  Each jump reduces the damage by ${$f*100}%.", description = "Scaglia spuntoni contro il bersaglio, infliggendo $s1 danni Fisici e saltando verso ${$x1-1} nemici aggiuntivi nelle vicinanze. Ogni salto riduce i danni del ${$f*100}%." },
    [1293184] = { en = "Gain the ability to purchase and craft your choice of Class Tier 1 Glove, Shoulder, or Boot recipes from Aisarra Nightmeadow.", description = "Ottieni la possibilità di acquistare e creare ricette a scelta tra Guanti, Spallacci o Stivali di classe di Grado 1 da Aisarra Nightmeadow." },
    [1293199] = { en = "Movement speed Increased by $s1% in The Barrens, Thousand Needles, Razorfen Kraul, and Razorfen Downs.", description = "La velocità di movimento aumenta del $s1% a The Barrens, Thousand Needles, Razorfen Kraul e Razorfen Downs." },
    [1293228] = { en = "Magmatus ignites the target, inflicting $s1 Fire damage and additional Fire damage every $t2 sec for $d.", description = "Magmatus incendia il bersaglio, infliggendo $s1 danni da Fuoco e danni da Fuoco aggiuntivi ogni $t2 s per $d." },
    [1293306] = { en = "Raise the severed head of Roogug, Horrifying and Silencing all Swine within $r yards for $d.", description = "Solleva la testa mozzata di Roogug, atterrendo e silenziando tutti i Swine entro $r metri per $d." },
    [1293327] = { en = "Inflicts Nature damage to nearby enemies, slowing them for up to $d.", description = "Infligge danni da Natura ai nemici vicini, rallentandoli per un massimo di $d." },
    [1293329] = { en = "Place on the hills along the north-western ridge of the summit.", description = "Posiziona sulle colline lungo il crinale nord-occidentale della vetta." },
    [1293331] = { en = "Your melee weapon attacks deal $1293333s1 Nature damage to both you and your target.\r\n", description = "Gli attacchi con la tua arma da mischia infliggono $1293333s1 danni da Natura sia a te che al bersaglio.\r\n" },
    [1293333] = { en = "Melee weapon attacks deal $1293333s1 Nature damage to both you and your target.", description = "Gli attacchi con armi da mischia infliggono $1293333s1 danni da Natura sia a te che al bersaglio." },
    [1293342] = { en = "When damaged, has a chance to grant you $1293345s1 armor for $1293345d.", description = "Quando subisci danni, hai una probabilità di ottenere $1293345s1 armatura per $1293345d." },
    [1293354] = { en = "Tailoring +$s1.", description = "Cucito +$s1." },
    [1293359] = { en = "Dunk the venomous heart in the Well of Eternity. Wait a second...", description = "Immergi il cuore velenoso nel Pozzo dell'Eternità. Attendi un secondo..." },
    [1293429] = { en = "Deal $s1 Fire damage and increase the target's damage taken from this effect by $s1.  Stacks up to $1293451s2 times.", description = "Infligge $s1 danni da Fuoco e aumenta di $s1 i danni subiti dal bersaglio da questo effetto. Si accumula fino a $1293451s2 volte." },
    [1293433] = { en = "Melee attacks with this weapon torture the target, dealing $1293429s1 Fire damage and increasing your damage dealt to that target with this effect by $1293429s1, stacking up to $1293451u times.", description = "Gli attacchi in mischia con quest'arma torturano il bersaglio, infliggendo $1293429s1 danni da Fuoco e aumentando di $1293429s1 i danni inflitti da te a quel bersaglio con questo effetto, fino a un massimo di $1293451u accumuli." },
    [1293482] = { en = "Discipline the target, dealing $s1 Physical damage.  Canines and Hyena are Stunned and sit for $1293483d.", description = "Punisci il bersaglio, infliggendo $s1 danni Fisici. Canidi e Iene vengono storditi e si siedono per $1293483d." },
    [1293515] = { en = "Wring out the Well of Eternity water from the Runecloth on to the venomous chimaera heart.", description = "Strizza l'acqua del Pozzo dell'Eternità dalla Telaruna sul cuore della chimera velenosa." },
    [1293539] = { en = "Deals $s1 Holy damage every time you block.", description = "Infligge $s1 danni Sacri ogni volta che pari un attacco." },
    [1293540] = { en = "Reduces the cast time of spells and effects that revive targets by $s1%.", description = "Riduce del $s1% il tempo di lancio degli incantesimi e degli effetti che rianimano i bersagli." },
    [1293542] = { en = "Gives you a $s1% chance to avoid interruption caused by damage while casting Flash Heal.", description = "Ti conferisce una probabilità del $s1% di evitare interruzioni causate dai danni mentre lanci Flash Heal." },
    [1293544] = { en = "Increases the critical strike chance of your Flash of Light by $s1%.\r\n", description = "Aumenta del $s1% la probabilità di colpo critico di Flash of Light.\r\n" },
    [1293657] = { en = "You are fluent in the following languages:$?s668[\r\n$@spellname668][]$?s669[\r\n$@spellname669][]$?s670[\r\n$@spellname670][]$?s671[\r\n$@spellname671][]$?s672[\r\n$@spellname672][]$?s813[\r\n$@spellname813][]$?s814[\r\n$@spellname814][]$?s815[\r\n$@spellname815][]$?s816[\r\n$@spellname816][]$?s817[\r\n$@spellname817][]$?s7340[\r\n$@spellname7340][]$?s7341[\r\n$@spellname7341][]$?s17737[\r\n$@spellname17737][]$?s25674[\r\n$@spellname25674][]$?s462134[\r\n$@spellname462134][]", description = "Conosci fluentemente le seguenti lingue:$?s668[\r\n$@spellname668][]$?s669[\r\n$@spellname669][]$?s670[\r\n$@spellname670][]$?s671[\r\n$@spellname671][]$?s672[\r\n$@spellname672][]$?s813[\r\n$@spellname813][]$?s814[\r\n$@spellname814][]$?s815[\r\n$@spellname815][]$?s816[\r\n$@spellname816][]$?s817[\r\n$@spellname817][]$?s7340[\r\n$@spellname7340][]$?s7341[\r\n$@spellname7341][]$?s17737[\r\n$@spellname17737][]$?s25674[\r\n$@spellname25674][]$?s462134[\r\n$@spellname462134][]" },
    [1293670] = { en = "Taking damage while at or below $s1% health grants you a shield, absorbing $1293733s2 damage for $1293733d.  This effect can only trigger once every ${$proccooldown/60} min.", description = "Subire danni con salute pari o inferiore al $s1% ti conferisce uno scudo che assorbe $1293733s2 danni per $1293733d. Questo effetto può attivarsi solo una volta ogni ${$proccooldown/60} min." },
    [1293674] = { en = "Taking damage has a $h% chance to grant Enraging Light for $1293673d, causing your melee attacks to deal $1293675s1 Holy damage. Deals $s1 times as much damage to Undead.", description = "Subire danni ha una probabilità del $h% di conferire Luce Furiosa per $1293673d, facendo sì che i tuoi attacchi in mischia infliggano $1293675s1 danni Sacri. Infligge agli Erranti la quantità di danni moltiplicata per $s1." },
    [1293682] = { en = "Gilnean Sharks are attacking! Taking damage equal to $s1% of your health every $t1 sec for $d.\r\n", description = "Gli squali gilneani stanno attaccando! Subisci danni pari al $s1% della tua salute ogni $t1 s per $d.\r\n" },
    [1293695] = { en = "Your Searing Pain generates $s1% less threat and brands the target for $1293696d. Your pet's next $m2 attacks against the target generate high threat and deal $<minDam> to $<maxDam> Fire or Shadow damage based on the pet.", description = "Searing Pain genera il $s1% di minaccia in meno e marchia il bersaglio per $1293696d. I prossimi $m2 attacchi del tuo famiglio contro il bersaglio generano molta minaccia e infliggono da $<minDam> a $<maxDam> danni da Fuoco o da Ombra, a seconda del famiglio." },
    [1293697] = { en = "Consuming a brand deals $<minDam> to $<maxDam> Shadow damage.", description = "Consumare un marchio infligge da $<minDam> a $<maxDam> danni da Ombra." },
    [1293698] = { en = "Consuming a brand deals Fire $<minDam> to $<maxDam> damage.", description = "Consumare un marchio infligge da $<minDam> a $<maxDam> danni da Fuoco." },
    [1293699] = { en = "Consuming a brand deals $s1 Physical damage.", description = "Consumare un marchio infligge $s1 danni Fisici." },
    [1293701] = { en = "$h% chance when struck in combat to gain $1293700s1 mana per 5 sec for $1293700d.", description = "Probabilità del $h% quando vieni colpito in combattimento di ottenere $1293700s1 mana ogni 5 s per $1293700d." },
    [1293712] = { en = "You are proficient in the use of the following armor types:$?s9078[\r\n$@spellname9078][]$?s9077[\r\n$@spellname9077][]$?s8737[\r\n$@spellname8737][]$?s750[\r\n$@spellname750][]", description = "Sai usare con competenza i seguenti tipi di armatura:$?s9078[\r\n$@spellname9078][]$?s9077[\r\n$@spellname9077][]$?s8737[\r\n$@spellname8737][]$?s750[\r\n$@spellname750][]" },
    [1293714] = { en = "Launch a magic severing bolt at the target, dealing $s1 Physical damage and interrupting the spell being cast for $d.", description = "Scaglia un dardo magico recisore contro il bersaglio, infliggendo $s1 danni Fisici e interrompendo l'incantesimo in corso per $d." },
    [1293740] = { en = "Increases your Stamina by $s1. While in Mount Hyjal, Hyjal Summit, and the Barrow Deeps, you also gain $s2% Hit Chance.\r\n\r\nLasts for $d. You can only have the effect of one flask at a time. This effect persists through death.", description = "Aumenta la tua Tempra di $s1. Mentre ti trovi a Mount Hyjal, Hyjal Summit e Barrow Deeps, ottieni anche $s2% di probabilità di colpire.\r\n\r\nDura $d. Puoi avere l'effetto di una sola fiasca alla volta. Questo effetto persiste anche dopo la morte." },
    [1293741] = { en = "Increases your Stamina by $s1. While in Mount Hyjal, Hyjal Summit, and the Barrow Deeps, you also gain $s2% Critical Strike Chance.\r\n\r\nLasts for $d. You can only have the effect of one flask at a time. This effect persists through death.", description = "Aumenta la tua Tempra di $s1. Mentre ti trovi a Mount Hyjal, Hyjal Summit e Barrow Deeps, ottieni anche $s2% di probabilità di colpo critico.\r\n\r\nDura $d. Puoi avere l'effetto di una sola fiasca alla volta. Questo effetto persiste anche dopo la morte." },
    [1293742] = { en = "Increases your Stamina by $s1. While in Mount Hyjal, Hyjal Summit, and the Barrow Deeps, you also gain $s2% reduced chance to be dodged or parried.\r\n\r\nLasts for $d. You can only have the effect of one flask at a time. This effect persists through death.", description = "Aumenta la tua Tempra di $s1. Mentre ti trovi a Mount Hyjal, Hyjal Summit e Barrow Deeps, ottieni anche una riduzione del $s2% della probabilità di essere schivato o parato.\r\n\r\nDura $d. Puoi avere l'effetto di una sola fiasca alla volta. Questo effetto persiste anche dopo la morte." },
    [1293743] = { en = "Increases your Stamina by $s1. While in Mount Hyjal, Hyjal Summit, and the Barrow Deeps, you also gain $s2% Haste.\r\n\r\nLasts for $d. You can only have the effect of one flask at a time. This effect persists through death.", description = "Aumenta la tua Tempra di $s1. Mentre ti trovi a Mount Hyjal, Hyjal Summit e Barrow Deeps, ottieni anche $s2% di velocità d'attacco.\r\n\r\nDura $d. Puoi avere l'effetto di una sola fiasca alla volta. Questo effetto persiste anche dopo la morte." },
    [1293787] = { en = "Unleash a mighty swing, dealing $s1 Holy damage. Deals $s2 times as much damage to Undead and Swine.", description = "Scatena un potente fendente, infliggendo $s1 danni Sacri. Infligge agli Erranti e agli Swine la quantità di danni moltiplicata per $s2." },
    [1293800] = { en = "Empty the contents of the leather-bound flask into the shallows of the pool of water inside Deadwood Den.", description = "Svuota il contenuto della fiasca rilegata in cuoio nelle acque basse dello specchio d'acqua all'interno di Deadwood Den." },
    [1293801] = { en = "A strange mist emanates from this creature, hiding all nearby players and creatures from view.", description = "Una strana nebbia emana da questa creatura, nascondendo alla vista tutti i giocatori e le creature nelle vicinanze." },
    [1293805] = { en = "Call upon newly awakened power to increase the limit of Artisan's Tier items you can equip to $s2.", description = "Invoca un potere appena risvegliato per aumentare a $s2 il limite di oggetti di Grado dell'Artigiano che puoi equipaggiare." },
    [1293806] = { en = "Permanently enchant a head slot item to give $ec1 Attack Power.", description = "Incanta permanentemente un oggetto per la testa, conferendo $ec1 potenza d'attacco." },
    [1293807] = { en = "Permanently enchant a head slot item to give $ec1 Spell Power.", description = "Incanta permanentemente un oggetto per la testa, conferendo $ec1 potenza magica." },
    [1293808] = { en = "Permanently enchant a head slot item to give $ec1 Stamina.", description = "Incanta permanentemente un oggetto per la testa, conferendo $ec1 tempra." },
    [1293809] = { en = "Permanently enchant a head slot item to give $ec1 Healing Power and $ec2 Spell Damage.", description = "Incanta permanentemente un oggetto per la testa, conferendo $ec1 potenza di guarigione e $ec2 danni magici." },
    [1293815] = { en = "Spells and attacks against Swine deal $1293814s1 Physical damage.", description = "Gli incantesimi e gli attacchi contro gli Swine infliggono $1293814s1 danni Fisici." },
    [1293816] = { en = "Increases all Shadow damage done by $s1%.", description = "Aumenta del $s1% tutti i danni da Ombra inflitti." },
    [1293820] = { en = "Increases your chance to Dodge by $s1% for $d. This effect is doubled in Strongholds and Cities.", description = "Aumenta del $s1% la tua probabilità di schivata per $d. Questo effetto raddoppia in Fortezze e Città." },
    [1293881] = { en = "Each swing alternates your attack speed between $1293885s1% faster and $1293886s1% slower.", description = "Ogni fendente alterna la velocità d'attacco tra il $1293885s1% più veloce e il $1293886s1% più lenta." },
    [1293885] = { en = "Melee attack speed increased by $s1%.", description = "La velocità d'attacco in mischia aumenta del $s1%." },
    [1293886] = { en = "Melee attack speed slowed by $s1%.", description = "La velocità d'attacco in mischia diminuisce del $s1%." },
    [1293889] = { en = "Attempts to freeze Elder Minderel in place, locking him in a block of ice and making him weak to Fire effects.", description = "Tenta di immobilizzare Elder Minderel, intrappolandolo in un blocco di ghiaccio e rendendolo vulnerabile agli effetti di Fuoco." },
    [1293928] = { en = "Inflicts $S1 shadow damage immediately, then $S2 shadow damage every $T2 sec for $d.", description = "Infligge subito $S1 danni da ombra, poi $S2 danni da ombra ogni $T2 sec per $d." },
    [1293958] = { en = "$@spelldesc1288961", description = "$@spelldesc1288961" },
    [1293980] = { en = "Chance on harmful spell cast to blast a target for $18083s1 Fire damage.", description = "Probabilità, quando lanci un incantesimo dannoso, di colpire un bersaglio con un'esplosione che infligge $18083s1 danni da Fuoco." },
    [1294006] = { en = "$@spelldesc1131 If you spend at least 10 seconds eating you will become well fed and gain $1294007s2% movement speed while in Hyjal for $1294007d. $@spelldesc1243969", description = "$@spelldesc1131 Se mangi per almeno 10 secondi, sarai ben nutrito e otterrai $1294007s2% alla velocità di movimento mentre ti trovi a Hyjal per $1294007d. $@spelldesc1243969" },
    [1294025] = { en = "Restores $s1 Mana.", description = "Ripristina $s1 mana." },
    [1294054] = { en = "Permanently enchant a pair of gloves to give a small chance to acquire Death Lotus when gathering any herb in Hyjal.", description = "Incanta permanentemente un paio di guanti, conferendo una probabilità ridotta di trovare Death Lotus quando raccogli erbe a Hyjal." },
    [1294055] = { en = "Chance on hit to reduce the mana cost of your next spell cast within $1294058d by $1294058s1.", description = "Probabilità, quando colpisci, di ridurre il costo in mana del tuo prossimo incantesimo lanciato entro $1294058d di $1294058s1." },
    [1294058] = { en = "Reduces the mana cost of your next spell cast by $s1.", description = "Riduce il costo in mana del tuo prossimo incantesimo lanciato di $s1." },
    [1294063] = { en = "Calls forth a Barkskin Ancestor to fight at your side and heal you for $d.", description = "Evoca un Antenato dalla Pelle di Corteccia che combatte al tuo fianco e ti cura per $d." },
    [1294064] = { en = "While in combat, your healing spells have a chance to grant an ally $1294065s1 armor for $1294065d.", description = "Mentre sei in combattimento, i tuoi incantesimi di cura hanno una probabilità di conferire a un alleato $1294065s1 armatura per $1294065d." },
    [1294071] = { en = "Increases your Attack Power by $s1.", description = "Aumenta la tua potenza d'attacco di $s1." },
    [1294087] = { en = "Your attacks have a chance to increase your Attack Power by $1294071s1 and your healing spells have a chance to increase your Intellect by $1294070s1 for $1294071d.", description = "I tuoi attacchi hanno una probabilità di aumentare la tua potenza d'attacco di $1294071s1 e i tuoi incantesimi di cura hanno una probabilità di aumentare la tua intelletto di $1294070s1 per $1294071d." },
    [1294234] = { en = "Combines Axe of Lingering Dread and Axe of Inevitable Ruin to reconstruct the Pendulum of Doom.", description = "Combina Axe of Lingering Dread e Axe of Inevitable Ruin per ricostruire Pendulum of Doom." },
    [1294243] = { en = "Increases your chance to Parry attacks by $s1% for $d.", description = "Aumenta la probabilità di parare gli attacchi di $s1% per $d." },
    [1294254] = { en = "Periodically summons Zombie Trolls of Zum'rah.", description = "Evoca periodicamente Troll Zombi di Zum'rah." },
    [1294255] = { en = "Chance on harmful spell cast to summon a Zombie Troll of Zum'rah for $1294258d.", description = "Probabilità, quando lanci un incantesimo dannoso, di evocare un Troll Zombi di Zum'rah per $1294258d." },
    [1294270] = { en = "Imbues your weapon with Fire granting a chance to inflict Fire damage on attacks, dealing $1294269s1 Fire damage every $1294269t2 sec.", description = "Imbeve la tua arma di Fuoco, conferendo agli attacchi una probabilità di infliggere danni da Fuoco: $1294269s1 danni da Fuoco ogni $1294269t2 sec." },
    [1294273] = { en = "Inflicts Frost damage to an enemy dealing $s1 Frost damage every $t2 sec and slowing movement speed.", description = "Infligge danni da Gelo a un nemico, infliggendo $s1 danni da Gelo ogni $t2 sec e rallentandone la velocità di movimento." },
    [1294274] = { en = "Imbues your weapon with Frost granting a chance to inflict Frost damage on attacks, slowing the enemies movement speed and dealing Frost damage every $1294273t2 sec.", description = "Imbeve la tua arma di Gelo, conferendo agli attacchi una probabilità di infliggere danni da Gelo, rallentando la velocità di movimento dei nemici e infliggendo danni da Gelo ogni $1294273t2 sec." },
    [1294314] = { en = "Tosses a torch at the target area.", description = "Lancia una torcia nell'area bersaglio." },
    [1294339] = { en = "Deal $s1 Physical damage and stun for $1294340d.  Trolls take $s2 times damage and stun duration.", description = "Infligge $s1 danni fisici e stordisce per $1294340d. I Troll subiscono $s2 volte i danni e la durata dello stordimento." },
    [1294430] = { en = "Lash the enemy with the rage of Sul'thraze, reducing their attack power by $s2 for $d and dealing $s1 Shadow damage. After $1294431d, the target suffers an additional $1294431s1 Shadow damage. This additional Shadow damage deals $s5 times as much damage to Trolls.", description = "Colpisci il nemico con la furia di Sul'thraze, riducendone la potenza d'attacco di $s2 per $d e infliggendo $s1 danni da ombra. Dopo $1294431d, il bersaglio subisce altri $1294431s1 danni da ombra. Questi danni da ombra aggiuntivi infliggono ai Troll danni pari a $s5 volte tanto." },
    [1294477] = { en = "Movement can generate Static Electricity.", description = "Il movimento può generare elettricità statica." },
    [1294482] = { en = "$s1 Fire damage inflicted.", description = "Inflitti $s1 danni da Fuoco." },
    [1294530] = { en = "Chance on hit to light the target ablaze, dealing $1294537s1 Fire damage over $1294537d.", description = "Probabilità, quando colpisci, di incendiare il bersaglio, infliggendo $1294537s1 danni da Fuoco in $1294537d." },
    [1294601] = { en = "Deals $S1 nature damage to all enemies within $r1 yards of the target.", description = "Infligge $S1 danni da natura a tutti i nemici entro $r1 metri dal bersaglio." },
    [1294617] = { en = "Transform all enemies within $r yards into scarabs, slowing movement speed by $s1% for $d. Qiraji and Silithid targets are stunned for $1294626d.", description = "Trasforma tutti i nemici entro $r metri in scarabei, rallentandone la velocità di movimento del $s1% per $d. I bersagli Qiraji e Silitidi vengono storditi per $1294626d." },
    [1294620] = { en = "You have looked into the afterlife and Kathris looked back. Feared.\r\n", description = "Hai guardato nell'aldilà e Kathris ha ricambiato lo sguardo. Temuto.\r\n" },
    [1294644] = { en = "Chance on harmful spell cast to afflict the target with a draining ritual, leeching $1294645s1 health every $1294645t1 sec for $1294645d.", description = "Probabilità, quando lanci un incantesimo dannoso, di affliggere il bersaglio con un rituale prosciugante, sottraendogli $1294645s1 salute ogni $1294645t1 sec per $1294645d." },
    [1294645] = { en = "Drain $s1 health, transferring it to the caster every $t1 for $d.", description = "Prosciuga $s1 salute e la trasferisce a chi lancia l'incantesimo ogni $t1 per $d." },
    [1294646] = { en = "Increases mount speed by $s1% in Desert areas.", description = "Aumenta la velocità della cavalcatura di $s1% nelle zone desertiche." },
    [1294668] = { en = "When struck in combat has a chance to energize you for $1294666s1 mana. This effect cannot occur more than once every $proccooldown seconds.", description = "Quando vieni colpito in combattimento, c'è una probabilità di fornirti $1294666s1 mana. Questo effetto non può verificarsi più di una volta ogni $proccooldown secondi." },
    [1294740] = { en = "Depressurizing?", description = "Depressurizzazione?" },
    [1294777] = { en = "Reduces the duration of all poison effects applied to you by $m1%.", description = "Riduce la durata di tutti gli effetti di veleno applicati su di te del $m1%." },
    [1294788] = { en = "Increases your chance to hit with spells by $s1%.\r\nIncreases your chance to hit with attacks and abilities by $s2%.\r\nReduces the chance for your attacks to be dodged by $s3%.\r\nReduces the chance for your attacks to be parried by $s4%.", description = "Aumenta la probabilità di colpire con gli incantesimi del $s1%.\r\nAumenta la probabilità di colpire con attacchi e abilità del $s2%.\r\nRiduce la probabilità che i tuoi attacchi vengano schivati del $s3%.\r\nRiduce la probabilità che i tuoi attacchi vengano parati del $s4%." },
    [1294794] = { en = "Chance on hit to restore $21951s1 mana. Restore $s1 times as much if attacking an Earth Elemental, Golem, or Titan-forged enemy.\r\n", description = "Probabilità, quando colpisci, di ripristinare $21951s1 mana. Ripristina una quantità di mana pari a $s1 volte tanto quando attacchi un Elementale della Terra, un Golem o un nemico forgiato dai Titani.\r\n" },
    [1294848] = { en = "$@spelldesc1288388", description = "$@spelldesc1288388" },
    [1294874] = { en = "$@spelldesc1271351", description = "$@spelldesc1271351" },
    [1294888] = { en = "$@spelldesc1271351", description = "$@spelldesc1271351" },
    [1294914] = { en = "$@spelldesc1271351", description = "$@spelldesc1271351" },
    [1294929] = { en = "$@spelldesc1271351", description = "$@spelldesc1271351" },
    [1294939] = { en = "Adds $s1 Frost damage to your melee attacks.", description = "Aggiunge $s1 danni da Gelo ai tuoi attacchi in mischia." },
    [1295039] = { en = "Deal $s1 Fire damage to your current target and an additional $o2 damage over $d. Deals $s3 times as much damage to Beast and Serpentine targets.", description = "Infligge $s1 danni da Fuoco al bersaglio attuale e altri $o2 danni in $d. Infligge ai bersagli Bestia e Serpentino una quantità di danni pari a $s3 volte tanto." },
    [1295064] = { en = "When struck in melee combat, has a $h% chance of stealing $1295065s1 life from target enemy.", description = "Quando vieni colpito in mischia, hai una probabilità del $h% di sottrarre $1295065s1 salute al nemico bersaglio." },
    [1295197] = { en = "Coats a weapon with poison that lasts for 30 minutes.\r\nEach strike has a $h% chance of poisoning the enemy, increasing their casting time by $11398s1% for $11398d.  100 charges.", description = "Ricopre un'arma di veleno che dura 30 minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, aumentando il suo tempo di lancio del $11398s1% per $11398d.  100 cariche." },
    [1295270] = { en = "Deal $s1 Physical damage split between up to $s3 nearby enemies. Deals $s2 times as much damage to Plants.", description = "Infligge $s1 danni fisici suddivisi tra un massimo di $s3 nemici vicini. Infligge alle Piante una quantità di danni pari a $s2 volte tanto." },
    [1295271] = { en = "Marks a target for delivery. After landing $s1 to $s2 spells or attacks, deal $1295633s1 Fire damage. Number of spells or attacks is halved in Snowy areas.", description = "Marca un bersaglio per la consegna. Dopo avergli inflitto da $s1 a $s2 incantesimi o attacchi, infligge $1295633s1 danni da Fuoco. Nelle zone innevate, il numero di incantesimi o attacchi viene dimezzato." },
    [1295272] = { en = "Page Everlook Emergency Services for a Parachute-Priest that will assist in healing allies for $1295661d.", description = "Contatta i Servizi di Emergenza di Everlook per richiedere un Sacerdote-Paracadutista che aiuterà a curare gli alleati per $1295661d." },
    [1295298] = { en = "Hold the scabbard and beckon the Veteran of the Third War to your side at a place from his memory.", description = "Impugna il fodero e richiama al tuo fianco il Veterano della Terza Guerra in un luogo che gli è caro." },
    [1295313] = { en = "Take steady aim and fire a round to knock your target away.", description = "Prendi la mira con calma e spara un colpo che scaglia via il bersaglio." },
    [1295387] = { en = "Summons and dismisses a rideable skeletal warhorse.  This is a very fast mount.", description = "Evoca e congeda un destriero da guerra scheletrico cavalcabile. È una cavalcatura molto veloce." },
    [1295608] = { en = "Attempts to remove $s1 Curse or Bane, and $s2 Disease from the igniter.", description = "Tenta di rimuovere $s1 maledizione o maleficio e $s2 malattia da chi accende la miccia." },
    [1295633] = { en = "$@spelldesc1295271", description = "$@spelldesc1295271" },
    [1295639] = { en = "Reduces movement speed by $s1% and increases Fire damage taken by all targets in a $a1 yard radius by $s2 for $d.", description = "Riduce la velocità di movimento del $s1% e aumenta i danni da Fuoco subiti da tutti i bersagli entro $a1 metri di raggio di $s2 per $d." },
    [1295661] = { en = "$@spelldesc1295272", description = "$@spelldesc1295272" },
    [1295678] = { en = "Summons and dismisses a rideable galestrider crane.", description = "Evoca e congeda una gru cavalcabile galestrider." },
    [1295720] = { en = "Imbue a staff with magic for 1 hour, increasing damage done by Fire spells and effects by up to $1306515s1.", description = "Infondi un bastone di magia per 1 ora, aumentando fino a $1306515s1 i danni inflitti dagli incantesimi e dagli effetti di Fuoco." },
    [1295736] = { en = "Launch a boulder dealing $s1 Physical damage.", description = "Scaglia un masso che infligge $s1 danni fisici." },
    [1295744] = { en = "Disease target for $s1 Nature damage every $t1 sec for $d. Deals $s2 times as much damage to Aquatic enemies.", description = "Infligge al bersaglio $s1 danni da Natura ogni $t1 s per $d. Infligge danni pari a $s2 volte contro i nemici acquatici." },
    [1295778] = { en = "Consolidate an ally's financial obligations to heal them for $s1 over  $d.", description = "Consolida gli obblighi finanziari di un alleato per curarlo di $s1 in $d." },
    [1295779] = { en = "Maximize an ally's savings, healing them for $s1.", description = "Massimizza i risparmi di un alleato, curandolo di $s1." },
    [1295780] = { en = "Strike a bargain with an ally to shield them against $s1 damage for up to $d.", description = "Stringi un patto con un alleato per proteggerlo da $s1 danni per un massimo di $d." },
    [1295904] = { en = "Equip: Increases attack power by X.", description = "Equipaggiamento: aumenta la potenza d'attacco di X." },
    [1296072] = { en = "The sheep casts on Player to give player condition for Quest Credit", description = "La pecora lancia l'incantesimo su Player per dare al giocatore la condizione necessaria per il credito missione" },
    [1296076] = { en = "Cast upon interacting with the sheep, this causes the sheep to set off an action trigger to make itself uninteractable.", description = "Lanciato interagendo con la pecora, la induce ad attivare un trigger d'azione che la rende non interagibile." },
    [1296202] = { en = "Summon a faithful rat familiar for $d. Its presence increases your Intellect by $s2.", description = "Evoca un fedele ratto famiglio per $d. La sua presenza aumenta il tuo intelletto di $s2." },
    [1296225] = { en = "Imbue a dagger with magic for 1 hour, causing it to occasionally chill foes when hit.", description = "Infondi un pugnale di magia per 1 ora, facendogli occasionalmente gelare i nemici quando vengono colpiti." },
    [1296534] = { en = "Summons a Forsaken Charger, which serves as a mount.", description = "Evoca un Destriero dei Reietti, che funge da cavalcatura." },
    [1296564] = { en = "Stuns target Undead for $d.", description = "Stordisce il bersaglio Non Morto per $d." },
    [1296596] = { en = "You have $RA resistance to Arcane, reducing average Arcane damage taken and chance to be hit by Arcane spells by ${$RA*75/($PL*5)}.2%.", description = "Hai una resistenza all'Arcano pari a $RA, che riduce i danni medi da Arcano subiti e la probabilità di essere colpito dagli incantesimi d'Arcano del ${$RA*75/($PL*5)}.2%." },
    [1296597] = { en = "You have $RF resistance to Fire, reducing average Fire damage taken and chance to be hit by Fire spells by ${$RF*75/($PL*5)}.2%.", description = "Hai una resistenza al Fuoco pari a $RF, che riduce i danni medi da Fuoco subiti e la probabilità di essere colpito dagli incantesimi di Fuoco del ${$RF*75/($PL*5)}.2%." },
    [1296598] = { en = "You have $RFR resistance to Frost, reducing average Frost damage taken and chance to be hit by Frost spells by ${$RFR*75/($PL*5)}.2%.", description = "Hai una resistenza al Gelo pari a $RFR, che riduce i danni medi da Gelo subiti e la probabilità di essere colpito dagli incantesimi di Gelo del ${$RFR*75/($PL*5)}.2%." },
    [1296599] = { en = "You have $RN resistance to Nature, reducing average Nature damage taken and chance to be hit by Nature spells by ${$RN*75/($PL*5)}.2%.", description = "Hai una resistenza alla Natura pari a $RN, che riduce i danni medi da Natura subiti e la probabilità di essere colpito dagli incantesimi di Natura del ${$RN*75/($PL*5)}.2%." },
    [1296601] = { en = "You have $RS resistance to Shadow, reducing average Shadow damage taken and chance to be hit by Shadow spells by ${$RS*75/($PL*5)}.2%.", description = "Hai una resistenza all'Ombra pari a $RS, che riduce i danni medi da Ombra subiti e la probabilità di essere colpito dagli incantesimi d'Ombra del ${$RS*75/($PL*5)}.2%." },
    [1296663] = { en = "You have $sk43/$<sc> skill in $@spellname1296663.\r\n\r\nLevel $PL target:\r\nHit, Dodge, and Parry: ${$<hdp>}.1%\r\nCritical Hit: ${$<cr>}.1%\r\nGlancing Blow Penalty: ${$<gp>}%\r\nGlancing Blow Chance: ${$<gc>}%\r\n$@expandkey[\r\nLevel ${$PL+1} target:\r\nHit, Dodge, and Parry: ${$<hdp1>}.1%\r\nCritical Hit: ${$<cr1>}.1%\r\nGlancing Blow Penalty: ${$<gp1>}%\r\nGlancing Blow Chance: ${$<gc1>}%\r\n\r\nLevel ${$PL+2} target:\r\nHit, Dodge, and Parry: ${$<hdp2>}.1%\r\nCritical Hit: ${$<cr2>}.1%\r\nGlancing Blow Penalty: ${$<gp2>}%\r\nGlancing Blow Chance: ${$<gc2>}%\r\n\r\nLevel ${$PL+3} target:\r\nHit, Dodge, and Parry: ${$<hdp3>}.1%\r\nCritical Hit: ${$<cr3>}.1%\r\nGlancing Blow Penalty: ${$<gp3>}%\r\nGlancing Blow Chance: ${$<gc3>)}%\r\n\r\n$@spelldesc1302929\r\n]", description = "Hai $sk43/$<sc> punti abilità in $@spellname1296663.\r\n\r\nBersaglio di livello $PL:\r\nColpire, Schivare e Parare: ${$<hdp>}.1%\r\nColpo critico: ${$<cr>}.1%\r\nPenalità colpo strisciante: ${$<gp>}%\r\nProbabilità colpo strisciante: ${$<gc>}%\r\n$@expandkey[\r\nBersaglio di livello ${$PL+1}:\r\nColpire, Schivare e Parare: ${$<hdp1>}.1%\r\nColpo critico: ${$<cr1>}.1%\r\nPenalità colpo strisciante: ${$<gp1>}%\r\nProbabilità colpo strisciante: ${$<gc1>}%\r\n\r\nBersaglio di livello ${$PL+2}:\r\nColpire, Schivare e Parare: ${$<hdp2>}.1%\r\nColpo critico: ${$<cr2>}.1%\r\nPenalità colpo strisciante: ${$<gp2>}%\r\nProbabilità colpo strisciante: ${$<gc2>}%\r\n\r\nBersaglio di livello ${$PL+3}:\r\nColpire, Schivare e Parare: ${$<hdp3>}.1%\r\nColpo critico: ${$<cr3>}.1%\r\nPenalità colpo strisciante: ${$<gp3>}%\r\nProbabilità colpo strisciante: ${$<gc3>)}%\r\n\r\n$@spelldesc1302929\r\n]" },
    [1296664] = { en = "Charm target Furbolg for $d.  Only works on targets not in combat.", description = "Ammalia il Furbolg bersaglio per $d. Funziona solo sui bersagli fuori dal combattimento." },
    [1296730] = { en = "Blunderflame the target for $s1 Fire damage.", description = "Colpisce il bersaglio con una fiammata, infliggendo $s1 danni da Fuoco." },
    [1297085] = { en = "Chance on harmful spell cast to reduce target enemy's attack power by $1297082s1 for $1297082d.\r\n", description = "Probabilità quando si lancia un incantesimo dannoso di ridurre la potenza d'attacco del nemico bersaglio di $1297082s1 per $1297082d.\r\n" },
    [1297109] = { en = "Causes all Beasts in a $a2 yard radius to run away for $d.", description = "Fa fuggire tutte le Bestie entro $a2 metri di raggio per $d." },
    [1297448] = { en = "Increases your effective stealth detection level by ${$s1/5} for $d, then reduces your effective stealth detection level by ${$1297449s1/-5} for $1297449d.", description = "Aumenta il tuo livello effettivo di individuazione della furtività di ${$s1/5} per $d, poi riduce il tuo livello effettivo di individuazione della furtività di ${$1297449s1/-5} per $1297449d." },
    [1297608] = { en = "Right Click to summon and dismiss your slimeling.", description = "Clicca col tasto destro per evocare e congedare il tuo slimeling." },
    [1297626] = { en = "Target player loses all mana.", description = "Il giocatore bersaglio perde tutto il mana." },
    [1297653] = { en = "Noxious venom and fire erupt around you, inflicting $s1 damage.", description = "Un veleno e un fuoco nocivi erompono intorno a te, infliggendo $s1 danni." },
    [1297671] = { en = "Converts $s1% of your maximum health into $1297672s1% of your maximum mana, energy, or rage.", description = "Converte il $s1% della tua salute massima nel $1297672s1% del tuo mana, della tua energia o della tua rabbia massimi." },
    [1297672] = { en = "$s1% of maximum health converted into $s1% of maximum mana, rage, or energy.", description = "Il $s1% della salute massima convertito nel $s1% del mana, della rabbia o dell'energia massimi." },
    [1297705] = { en = "Disguise yourself as a member of the Syndicate. Suspicious activity will break the disguise.", description = "Travestiti da membro del Syndicate. Attività sospette faranno saltare il travestimento." },
    [1297762] = { en = "Perform a Propellerstorm, reducing your fall speed for $d and dealing $1297967s1% weapon damage to nearby enemies when you land.", description = "Esegui un Propellerstorm, riducendo la velocità di caduta per $d e infliggendo ai nemici vicini, all'atterraggio, danni pari al $1297967s1% dei danni dell'arma." },
    [1297774] = { en = "Suffuse yourself with magical energy, allowing the detection and acquisition of Motes of Unstable Magic from certain spellcasters and powerful enemies.", description = "Ti impregna di energia magica, consentendoti di rilevare e acquisire Mote di Magia Instabile da determinati incantatori e nemici potenti." },
    [1297921] = { en = "Cremate the target for $s1 Fire damage.", description = "Crema il bersaglio, infliggendo $s1 danni da Fuoco." },
    [1297967] = { en = "Deals $s1% weapon damage to nearby enemies.", description = "Infligge ai nemici vicini danni pari al $s1% dei danni dell'arma." },
    [1298392] = { en = "Use the fox fur to temporaily transform a demon in Dae'gun.", description = "Usa la pelliccia di volpe per trasformare temporaneamente un demone in Dae'gun." },
    [1298416] = { en = "Deal an additional $s2 Frost damage and slow movement speed by $s1% for $d.", description = "Infligge $s2 danni da Gelo aggiuntivi e riduce la velocità di movimento del $s1% per $d." },
    [1298437] = { en = "Melee attacks cause an additional $68960s1 Fire damage to all enemies within $68960a1 yards of the target.\r\n", description = "Gli attacchi in mischia infliggono $68960s1 danni da Fuoco aggiuntivi a tutti i nemici entro $68960a1 metri dal bersaglio.\r\n" },
    [1298450] = { en = "Summons and dismisses a rideable white kodo.", description = "Evoca e congeda un kodo bianco cavalcabile." },
    [1298494] = { en = "$@spelldesc2842", description = "$@spelldesc2842" },
    [1298497] = { en = "Releases the spirit from an Undead corpse within $a1 yds, laying it to rest and restoring $1298498s1 Health.", description = "Libera lo spirito da un cadavere Non Morto entro $a1 m, permettendogli di riposare e ripristinando $1298498s1 salute." },
    [1298498] = { en = "Redeem an Undead corpse, laying its spirit to rest and restoring $s1 Health. Only usable on Undead corpses within $1298497a1 yds.", description = "Concedi il riposo allo spirito di un cadavere Non Morto, ripristinando $s1 salute. Utilizzabile solo sui cadaveri Non Morti entro $1298497a1 m." },
    [1298499] = { en = "Melee attacks with this weapon deal $s1 Frost damage.", description = "Gli attacchi in mischia con quest'arma infliggono $s1 danni da Gelo." },
    [1298500] = { en = "Melee attacks with this weapon deal $1298499s1 Frost damage.", description = "Gli attacchi in mischia con quest'arma infliggono $1298499s1 danni da Gelo." },
    [1298627] = { en = "Reduces movement speed by $S2%. \r\n\r\nInflicts $1298630s1 Nature damage to self and nearby players every $t1 sec.", description = "Riduce la velocità di movimento del $S2%. \r\n\r\nInfligge a te e ai giocatori vicini $1298630s1 danni da Natura ogni $t1 s." },
    [1298630] = { en = "Inflicts $S1 nature damage to the player and all players within $r yards.", description = "Infligge $S1 danni da Natura al giocatore e a tutti i giocatori entro $r metri." },
    [1298707] = { en = "Sling the Explosive Runeshard at a target location to signal Maerion to attack.", description = "Scaglia la Scheggia Runica Esplosiva verso un punto bersaglio per segnalare a Maerion di attaccare." },
    [1298776] = { en = "Allows you to magically use reagents stored in your bank while crafting.", description = "Ti permette di usare magicamente in creazione i reagenti conservati nella tua banca." },
    [1298847] = { en = "The spirit struggles to maintain its form, suffering $s1% of maximum health as damage every $t1 sec.", description = "Lo spirito lotta per mantenere la propria forma, subendo danni pari al $s1% della salute massima ogni $t1 secondi." },
    [1298874] = { en = "The Wild King draws on the power of Nordrassil, increasing damage dealt by $S1% and haste by $S2%. ", description = "Il Re Selvaggio attinge al potere di Nordrassil, aumentando i danni inflitti del $S1% e la celerità del $S2%. " },
    [1299026] = { en = "Instantly removes and grants immunity to all Curses and Banes, and reduces all Magical damage taken by $s1% for $d.", description = "Rimuove istantaneamente tutte le Maledizioni e i Flagelli e conferisce immunità a essi, oltre a ridurre del $s1% tutti i danni magici subiti per $d." },
    [1299171] = { en = "The Emerald Dream fails to maintain its form, killing all players within.", description = "Il Sogno di Smeraldo non riesce a mantenere la propria forma, uccidendo tutti i giocatori al suo interno." },
    [1299303] = { en = "Charges the branch of Nordrassil with the power of Stormwraith.", description = "Carica il ramo di Nordrassil con il potere dello Spettro della Tempesta." },
    [1299323] = { en = "Achieved victory in this week's Stranglethorn Fishing Extravaganza! Permitted to wear the title \"Master Angler\" for the duration of this effect.", description = "Hai vinto la Stranglethorn Fishing Extravaganza di questa settimana! Puoi indossare il titolo \"Master Angler\" per la durata di questo effetto." },
    [1299341] = { en = "Summons a Bitter Baitling.", description = "Evoca un'esca amara." },
    [1299351] = { en = "Gain the ability to walk on water for $d.\r\n\r\nAttacking or taking damage will cancel this effect.", description = "Ottieni la capacità di camminare sull'acqua per $d.\r\n\r\nAttaccare o subire danni annulla questo effetto." },
    [1299437] = { en = "Increases the cast time of your Aimed Shot by ${$m2/1000} sec and its damage by $s1%.", description = "Aumenta il tempo di lancio di Tiro Mirato di ${$m2/1000} sec e i suoi danni del $s1%." },
    [1299440] = { en = "Fear all Demons within $r yards for $d.", description = "Impaurisce tutti i Demoni entro $r m per $d." },
    [1299443] = { en = "Harness the power of lightning to strike the target, stunning them for $d. Stuns players in water for $s1 times as long.", description = "Incanta il bersaglio con il potere del fulmine, stordendolo per $d. Stordisce i giocatori in acqua per un tempo $s1 volte più lungo." },
    [1299444] = { en = "Can't hold your breath.", description = "Non riesci a trattenere il respiro." },
    [1299631] = { en = "Smites a target for $s1 Holy damage. Deals $s2 times as much damage to Undead.", description = "Colpisce un bersaglio infliggendo $s1 danni sacri. Infligge ai Non Morti danni $s2 volte superiori." },
    [1299734] = { en = "Improves your chance to hit by ${$s1/10}.1%.", description = "Aumenta la probabilità di colpire di ${$s1/10}.1%." },
    [1299737] = { en = "Harmful spell casts have a chance to steal $1299735s1 life from target enemy.", description = "I lanci di incantesimi nocivi hanno una probabilità di sottrarre $1299735s1 salute al nemico bersaglio." },
    [1299738] = { en = "Improves your chance to get a critical strike by ${$s1/14}.1%.", description = "Aumenta la probabilità di infliggere un colpo critico di ${$s1/14}.1%." },
    [1299740] = { en = "Grants your melee attacks a chance to wound the target, causing them to Bleed for $1299739o damage over $1299739d.", description = "Conferisce ai tuoi attacchi in mischia una probabilità di ferire il bersaglio, facendolo Sanguinare per $1299739o danni in $1299739d." },
    [1299743] = { en = "Grants a chance when struck in combat to increase damage and healing done by magical spells and effects by up to $1299746s1 for $1299746d.", description = "Conferisce una probabilità, quando subisci un colpo in combattimento, di aumentare fino a $1299746s1 i danni e le cure inflitti da incantesimi ed effetti magici per $1299746d." },
    [1299796] = { en = "Increases your Spirit by $s1%.", description = "Aumenta lo Spirito del $s1%." },
    [1299943] = { en = "Deals $s1 damage per second.\r\nFeeding back $s1 health per second.", description = "Infligge $s1 danni al secondo.\r\nRestituisce $s1 salute al secondo." },
    [1299948] = { en = "Harmful spell casts have a chance to steal $1299943o1 life from target enemy over $1299943d.", description = "I lanci di incantesimi nocivi hanno una probabilità di sottrarre $1299943o1 salute al nemico bersaglio in $1299943d." },
    [1300128] = { en = "Melee attacks deal $1300130s1 Fire additional damage against Frozen targets.", description = "Gli attacchi in mischia infliggono $1300130s1 danni da fuoco aggiuntivi contro i bersagli congelati." },
    [1300130] = { en = "Deal $s2 Fire damage.", description = "Infligge $s2 danni da fuoco." },
    [1300141] = { en = "Melee attacks have a $h% chance to grant a Clearcasting state, reducing the mana cost of your next damage spell by 100%.", description = "Gli attacchi in mischia hanno una probabilità del $h% di conferire lo stato di Lancio Libero, riducendo del 100% il costo in mana del prossimo incantesimo che infligge danni." },
    [1300180] = { en = "Stealth to sneak around, but reduce your movement speed by $s2%.  Can only be used when out of combat.  Lasts $d.", description = "Entri in furtività per muoverti senza farti notare, ma la velocità di movimento si riduce del $s2%. Può essere usato solo fuori dal combattimento. Dura $d." },
    [1300209] = { en = "Bludgeon the target, dealing $s1 Physical damage.  Canines and Hyaenidae are stunned and sit for $1293483d.", description = "Colpisce il bersaglio, infliggendo $s1 danni fisici. I Canidi e gli Ienidi vengono storditi e si siedono per $1293483d." },
    [1300240] = { en = "Deals $s1 Nature damage per $t1 sec. Deaks $s2 times as much damage to Trolls.", description = "Infligge $s1 danni naturali ogni $t1 sec. Infligge ai Troll danni $s2 volte superiori." },
    [1300241] = { en = "Put to sleep for up to $d.  Any damage caused will awaken you.", description = "Ti addormenta per un massimo di $d. Qualsiasi danno subito ti risveglierà." },
